package main

import (
	"bufio"
	"fmt"
	"os"
)

type FScanner struct {
	scanner *bufio.Scanner
}

func NewFScanner() *FScanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return &FScanner{scanner: sc}
}

func (fs *FScanner) next() string {
	if fs.scanner.Scan() {
		return fs.scanner.Text()
	}
	return ""
}

func (fs *FScanner) nextInt() int {
	var x int
	fmt.Sscan(fs.next(), &x)
	return x
}

func (fs *FScanner) nextLong() int64 {
	var x int64
	fmt.Sscan(fs.next(), &x)
	return x
}

func (fs *FScanner) nextDouble() float64 {
	var x float64
	fmt.Sscan(fs.next(), &x)
	return x
}

func (fs *FScanner) nextLine() string {
	fs.scanner.Split(bufio.ScanLines)
	if fs.scanner.Scan() {
		return fs.scanner.Text()
	}
	return ""
}

func (fs *FScanner) nextCharArray(n, m int) [][]rune {
	g := make([][]rune, n)
	for i := 0; i < n; i++ {
		g[i] = []rune(fs.next())
	}
	return g
}

func (fs *FScanner) nextDoubleArray(n int) []float64 {
	a := make([]float64, n)
	for i := 0; i < n; i++ {
		a[i] = fs.nextDouble()
	}
	return a
}

func (fs *FScanner) nextIntArray(n int) []int {
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = fs.nextInt()
	}
	return a
}

func (fs *FScanner) nextLongArray(n int) []int64 {
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		a[i] = fs.nextLong()
	}
	return a
}

func run() {
	in := NewFScanner()
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := in.nextInt()
	a := make([]int, n)
	for i := 0; i < n; i++ {
		x := in.nextInt()
		a[i] = x
	}
	if a[0]%2 != 0 && a[n-1]%2 != 0 && n%2 == 1 {
		fmt.Fprint(out, "Yes")
	} else {
		fmt.Fprint(out, "No")
	}
}

